"""Generate docs/evaluation/EVALUATION.md from the results_*.json files (never hand-edited)."""
import json, math
from pathlib import Path

D = Path(__file__).resolve().parents[1] / "docs" / "evaluation"
load = lambda n: json.loads((D / f"results_{n}.json").read_text()) if (D / f"results_{n}.json").exists() else None


def wilson(k, n, z=1.96):
    if not n: return None
    p = k / n; d = 1 + z * z / n
    c = (p + z * z / (2 * n)) / d; h = z * math.sqrt(p * (1 - p) / n + z * z / (4 * n * n)) / d
    return max(0, c - h), min(1, c + h)


def r0(x): return "n/a" if x is None else f"{x:,.0f}"
def pc(x, d=1): return "n/a" if x is None else f"{100 * x:.{d}f}%"
def ci(k, n):
    w = wilson(k, n); return "n/a" if w is None else f"{pc(k / n)} [{pc(w[0])}–{pc(w[1])}]"
def tbl(head, rows): return "\n".join(["| " + " | ".join(head) + " |", "|" + "---|" * len(head)] + ["| " + " | ".join(str(c) for c in r) + " |" for r in rows])


def em_count(m): return round(m["exact_match"] * m["n"]) if m["exact_match"] is not None else 0


def main():
    T, T2, T2off, DEV, TPH = load("test"), load("test2"), load("test2_rule_off"), load("dev"), load("test_posthoc")
    env = T2["env"]; L = []
    A = L.append
    A("# Evaluation report\n")
    A("_Generated by `eval/report_eval.py` from `docs/evaluation/results_*.json` (produced by `eval/run_eval.py`). Do not edit by hand._\n")
    A("## 1. Read this first\n")
    A("- **All data is synthetic and generated by the same author as the extractor** (`eval/make_dataset.py`). The numbers below are an **upper bound** for real invoices: "
      "the layouts, labels and number formats were designed by me, so a high score shows the system handles *those* variations, not that it generalises to arbitrary documents. "
      "No real invoices were available; none were used.")
    A("- Protocol: `dev` (101 invoices) was used to debug and to choose one threshold. `test` (seed 202) was run **once, first, on frozen code** (commit "
      f"`{T['git_commit']}`) before any fix derived from it. After inspecting its errors I added word-level OCR confidence (section 5.4); because `test` was then inspected, "
      "that change is evaluated on a **fresh split `test2`** (seed 303) that was never inspected. Rerunning `test` with the new rule is shown only as a labeled post-hoc row.")
    A(f"- Environment (all runs): {env['platform']}; {env['cpu']}; {env['cores']} core(s); {env['ram_mb']} MB RAM; Python {env['python']}; PyMuPDF {env['pymupdf']}; {env['tesseract']}. "
      "Jobs ran one at a time. **This is not the target Windows / 8 GB machine; timings will differ there.**")
    A("- Sample sizes are small (about 200 invoices per held-out split, 3–60 invoices per file type). Intervals are 95% Wilson intervals; treat subgroup numbers as indicative.\n")

    A("## 2. Headline results (two independent held-out splits)\n")
    rows = []
    for name, R in (("test (seed 202, first run)", T), ("test2 (seed 303, fresh)", T2)):
        f = R["overall"]["fields_micro"]; li = R["overall"]["line_items"]; pr = R["processing"]
        n_valid = pr["valid_files"]; ok = round(pr["success_rate"] * n_valid)
        rows.append([name, f"{R['dataset']['valid_files']} / {R['dataset']['labeled_invoices']}", ci(ok, n_valid),
                     pc(pr["failure_rate"]), ci(em_count(f), f["n"]), f"{pc(f['precision'])} / {pc(f['recall'])}",
                     f"{pc(li['precision'])} / {pc(li['recall'])}", ci(round(R['overall']['invoice_all_correct_rate'] * R['overall']['invoices_truth']), R['overall']['invoices_truth'])])
    A(tbl(["split", "valid files / invoices", "processing success", "failure rate", "header-field exact match", "header P / R", "line-item P / R", "invoices fully correct"], rows))
    A("\n_Header fields = invoice number, date, supplier, customer, subtotal, tax, total, currency (8 per invoice). A correct “not present” counts as a match for exact-match accuracy. "
      "Zero failures in the valid files means the 95% upper bound on the failure rate is about 3/n (rule of three): "
      f"{pc(3 / T['processing']['valid_files'])} for each split, for files like these._\n")

    A("## 3. Dataset and metric definitions\n")
    ds = T["dataset"]
    A(f"`test`: {ds['files']} files ({ds['valid_files']} valid, {ds['negative_files']} deliberately broken), {ds['labeled_invoices']} labeled invoices. `test2` has the same composition with a different seed; "
      f"`dev` is a 40% sample. Valid files by type: " + ", ".join(f"{k} {v}" for k, v in ds["by_file_type"].items()) + ".")
    A("\nVariation: three invoice layouts (different labels: Invoice Number / Inv # / Invoice No.; Bill To / Sold To; Tax / VAT / GST; Total / Amount Due / Total Amount), supplier as a labeled or unlabeled first line, "
      "5 date formats, 3 invoice-number formats, thousands separators, `$`/`£` symbols or ISO codes, 2–6 line items, multi-invoice PDFs/TIFFs/workbooks (multi-sheet), CSV with `,` `;` tab delimiters, "
      "one-invoice-per-row Excel registers, scans at 200 dpi, blurred / half-resolution / 2°-rotated images, missing fields, ambiguous dates, tampered totals, line-arithmetic errors, duplicate and cross-document pairs, "
      "and corrupt / empty / encrypted / unsupported / mislabeled / blank files.")
    A("\n**Metrics.** *Exact match*: value equals the label exactly (amounts compared as decimals; dates as ISO; text after trimming). *Precision* = correct ÷ values the system produced; *recall* = correct ÷ values present in the label; "
      "*exact-match accuracy* = matches ÷ all field instances, counting a correct “absent” as a match. *Line item* is correct only if description, quantity, unit price and amount all match. "
      "*Success* = the file reached `completed`/`partial` with at least one invoice; *failure* = it ended `failed`. Predicted and labeled invoices are paired by invoice number (fallback: order).")
    A("\n**Not covered (generator limits):** euro-symbol invoices (the PDF font cannot draw €), non-English text, handwriting, stamps/logos/background noise, skew above 2°, multi-column or wrapped table layouts, "
      "discount/shipping lines, tax-inclusive pricing, real scanner artefacts, PDFs mixing images and text layers.\n")

    A("## 4. Processing reliability and speed\n")
    rows = []
    for ft in T["processing"]["by_file_type"]:
        a, b = T["processing"]["by_file_type"][ft], T2["processing"]["by_file_type"].get(ft, {})
        ta, tb = T["timing"].get(ft, {}), T2["timing"].get(ft, {})
        rows.append([ft, f"{a['n']}+{b.get('n', 0)}", f"{a['success']}+{b.get('success', 0)}", f"{a.get('failed', 0)}+{b.get('failed', 0)}",
                     f"{ta.get('median_s')} / {tb.get('median_s')}", f"{ta.get('p95_s')} / {tb.get('p95_s')}", f"{r0(ta.get('pages_per_min'))} / {r0(tb.get('pages_per_min'))}"])
    A(tbl(["file type", "files (test+test2)", "succeeded", "failed", "median s/file (test / test2)", "p95 s/file", "pages/min"], rows))
    A("\n“Succeeded” = document ended `completed` or `partial` with at least one invoice. Time is the worker's processing time per file (upload excluded), single core, OCR at 200 dpi with the default settings "
      "(1 OCR thread, Tesseract capped to 1 thread). Digital files take milliseconds; OCR dominates everything else. These are small 1–2 page files; see `docs/benchmarks/` for 1,000-page runs.\n")
    neg = [r for R in (T, T2) for r in R["negatives"]["rows"]]
    handled = sum(r["handled"] for r in neg); codes = sum(r["handled"] and r["code_ok"] for r in neg)
    A(f"**Negative cases** (corrupt, truncated, empty, encrypted, unsupported, mislabeled, blank): {handled}/{len(neg)} ended in the expected outcome (rejected at upload, or failed with an error), "
      f"{codes}/{len(neg)} with the expected error code; maximum job attempts among them: {max((r['attempts'] or 0) for r in neg)} (permanent errors are not retried). "
      "Per category: " + ", ".join(f"{c} {sum(r['handled'] for r in neg if r['category'] == c)}/{sum(1 for r in neg if r['category'] == c)}" for c in sorted({r['category'] for r in neg})) + ".\n")

    A("## 5. Extraction accuracy\n")
    A("### 5.1 Per file type (both held-out splits)\n")
    rows = []
    for ft in sorted(set(T["by_file_type"]) | set(T2["by_file_type"])):
        a, b = T["by_file_type"].get(ft), T2["by_file_type"].get(ft)
        parts = [x for x in (a, b) if x]
        n = sum(x["invoices_truth"] for x in parts); fem = sum(em_count(x["fields_micro"]) for x in parts); fn_ = sum(x["fields_micro"]["n"] for x in parts)
        ac = sum(round(x["invoice_all_correct_rate"] * x["invoices_truth"]) for x in parts)
        tp = sum(x["line_items"]["tp"] for x in parts); fp = sum(x["line_items"]["fp"] for x in parts); fnn = sum(x["line_items"]["fn"] for x in parts)
        rows.append([ft, n, ci(fem, fn_), ci(ac, n), "n/a (register)" if tp + fnn == 0 else f"{pc(tp / (tp + fp) if tp + fp else None)} / {pc(tp / (tp + fnn))}"])
    A(tbl(["file type", "invoices", "header-field exact match", "invoice fully correct", "line-item P / R"], rows))
    A("\n`pdf+register` = the PDF and the register workbook of the cross-document pairs (digital PDFs; registers are one invoice per row). `png-degraded` = blurred, half-resolution and 2°-rotated images.")
    A("\n### 5.2 Per field (pooled over both splits)\n")
    rows = []
    for fld in T["overall"]["fields"]:
        a, b = T["overall"]["fields"][fld], T2["overall"]["fields"][fld]
        c, pn, tn, n = a["correct"] + b["correct"], a["pred_nonnull"] + b["pred_nonnull"], a["truth_nonnull"] + b["truth_nonnull"], a["n"] + b["n"]
        em = em_count(a) + em_count(b)
        rows.append([fld, tn, pc(c / pn if pn else None), pc(c / tn if tn else None), ci(em, n), a["hallucinated"] + b["hallucinated"]])
    A(tbl(["field", "present in truth", "precision", "recall", "exact match (incl. correct absence)", "values invented for absent fields"], rows))
    A("\n### 5.3 Where the errors are\n")
    rows = []
    for cat in sorted(set(T["by_category"]) | set(T2["by_category"])):
        parts = [x["by_category"][cat] for x in (T, T2) if cat in x["by_category"]]
        n = sum(p["invoices_truth"] for p in parts); ac = sum(round(p["invoice_all_correct_rate"] * p["invoices_truth"]) for p in parts)
        fem = sum(em_count(p["fields_micro"]) for p in parts); fn_ = sum(p["fields_micro"]["n"] for p in parts)
        rows.append([cat, n, pc(fem / fn_), pc(ac / n)])
    A(tbl(["category", "invoices", "header-field exact match", "invoice fully correct"], rows))
    errs = [json.loads(l) for n in ("test", "test2") for l in open(D / f"errors_{n}.jsonl")]
    import collections
    byfield = collections.Counter(e["field"] for e in errs)
    inv_nums = [e for e in errs if e["field"] == "invoice_number"]
    conf_conf = sum(1 for e in inv_nums if "SI/" in str(e["expected"]) and ("S1" in str(e["got"]) or "SV" in str(e["got"])))
    A(f"\nAcross both held-out splits there are {len(errs)} logged errors: " + ", ".join(f"{v} × {k}" for k, v in byfield.most_common()) + ". "
      f"Header-field errors occur only in these file types: {', '.join(sorted({e['file_type'] for e in errs if e['field'] not in ('line_items', 'invoice')})) or 'none'}. "
      f"{conf_conf} of {len(inv_nums)} invoice-number errors are one confusion: my synthetic "
      "`SI/…` number format read as `S1/…` or `SV…`. That is partly a dataset artifact (I chose an ambiguous prefix); other number formats were read correctly. "
      "Line-item errors are dropped/garbled rows and single-digit amount misreads in OCR'd tables. Full list: `errors_test.jsonl`, `errors_test2.jsonl`.\n")

    A("### 5.4 Validation, review flags, and the OCR-confidence rule\n")
    rules = {}
    for R in (T2,):
        for k, v in R["overall"]["rules"].items(): rules[k] = v
    UNSCORED = ("VAL-OCR-001", "VAL-LINE-003")
    rows = [[k, v["tp"], v["fp"], v["fn"], pc(v["precision"]), pc(v["recall"])] for k, v in rules.items() if k not in UNSCORED]
    A("Rule detection on `test2` (current code), scored per invoice against the rules each flawed document was *built* to trigger "
      "(tampered total → `VAL-SUB-001`, line error → `VAL-LINE-001`, missing field → `VAL-REQ-001`, ambiguous date → `VAL-DATE-002`, duplicate → `VAL-DUP-001`, document↔register mismatch/match → `VAL-XDOC-001/002`). "
      "False positives on OCR'd documents are mostly *correct* detections of OCR mistakes that the truth label (what was printed) does not contain.\n")
    A(tbl(["rule", "TP", "FP", "FN", "precision", "recall"], rows))
    A("\n`VAL-OCR-001` and `VAL-LINE-003` (OCR-quality warnings) are not in this table: no flawed document was built to trigger them, so label-based precision/recall is undefined. "
      f"On `test2` they fired {rules.get('VAL-OCR-001', {}).get('fp', 0)} and {rules.get('VAL-LINE-003', {}).get('fp', 0)} times; their usefulness is measured by the review-flag table below.")
    def rf(R): return R["overall"]["review_flags"]
    A("\nThree questions a reviewer cares about (flag = needs review):\n")
    def row(name, R):
        r = rf(R); return [name, f"{r['flagged_of_flawed']}/{r['flawed_documents_correctly_extracted']}", f"{r['flagged_of_error']}/{r['invoices_with_extraction_error']}  ({pc(r['error_catch_rate'], 0)})",
                           f"{r['flagged_of_clean']}/{r['clean_correct_invoices']}  ({pc(r['false_review_rate'], 1)})"]
    rows = [row("test, first run (no OCR-confidence rule)", T), row("test2, OCR rule OFF", T2off), row("**test2, OCR rule ON (floor 60) — current**", T2)]
    if TPH: rows.append(row("test + rule ON (post-hoc; split was inspected)", TPH))
    A(tbl(["run", "genuinely flawed documents flagged", "extraction errors flagged (“error catch”)", "clean invoices falsely flagged"], rows))
    sw = T2off["ocr_sweep"]
    A("\nEffect of the new `VAL-OCR-001` rule (weakest Tesseract word confidence behind a value below a floor): on the fresh split it raised error catch from "
      f"{rf(T2off)['flagged_of_error']}/{rf(T2off)['invoices_with_extraction_error']} to {rf(T2)['flagged_of_error']}/{rf(T2)['invoices_with_extraction_error']} at the price of "
      f"{rf(T2)['flagged_of_clean']} extra clean invoices flagged. The floor (60) was chosen on `dev` only (it caught all 8 dev errors with 1/21 false flags there). "
      "A what-if sweep on `test2` (informational; **not** used to tune) shows the trade-off depends on the data:\n")
    A(tbl(["floor", "errors caught (OCR invoices)", "clean OCR invoices falsely flagged"], [[x["floor"], f"{x['caught']}/{x['ocr_invoices_with_error']} ({pc(x['catch_rate'], 0)})", f"{x['falsely_flagged']}/{x['clean_ocr_invoices']} ({pc(x['false_review_rate'], 0)})"] for x in sw]))
    A("\nBefore the rule, silent errors were mainly misread invoice numbers (nothing arithmetic can catch). The page-level OCR average hides them (~94 vs ~91); the per-word confidence does not. "
      "With 16 errors per split the catch-rate difference is not statistically solid; the floor is configurable (`DOCINTEL_OCR_FIELD_MIN_CONF`, 0 disables) and should be tuned on real documents.\n")

    A("### 5.5 Is the confidence score calibrated?\n")
    A("No. Field `confidence` is a heuristic (rule strength × OCR word confidence), **not** an empirically calibrated probability. Observed accuracy per confidence bin on `test2` (current code):\n")
    A(tbl(["confidence bin", "fields", "mean stated confidence", "observed accuracy"], [[r["bin"], r["n"], r["mean_confidence"], r["empirical_accuracy"]] for r in T2["calibration"]]))
    rows5 = [r for r in T2["calibration"] if r["n"]]
    under = all(r["empirical_accuracy"] >= r["mean_confidence"] for r in rows5)
    accs = [r["empirical_accuracy"] for r in rows5]
    ranks = all(accs[i] <= accs[i + 1] + 1e-9 for i in range(len(accs) - 1))
    v1 = {r["bin"]: r for r in T["calibration"]}.get("0.70-0.85")
    A("\n" + ("Lower-confidence bins are less accurate than higher ones, so the score ranks fields usefully" if ranks else "Accuracy does not increase monotonically with the stated confidence")
      + ("; but stated confidence is below observed accuracy in every bin, so it is not a probability" if under else "; and it does not match observed accuracy, so it is not a probability") + ". "
      + (f"In the first `test` run (page-level OCR factor, before word-level confidence) the misread invoice numbers sat in the 0.70–0.85 bin together with correct values "
         f"(observed accuracy {v1['empirical_accuracy']} over {v1['n']} fields), i.e. the score did not separate them; with word-level OCR confidence the weakly read values now fall into the lower bins above. " if v1 else "")
      + "The review decision relies on the validation rules above, not on this number.\n")

    A("## 6. Generalisation check (dev vs held-out)\n")
    d = DEV["overall"]["fields_micro"]; t = T["overall"]["fields_micro"]
    A(f"`dev` (used for debugging) header exact match {pc(d['exact_match'])}, invoices fully correct {pc(DEV['overall']['invoice_all_correct_rate'])}; `test` {pc(t['exact_match'])} / {pc(T['overall']['invoice_all_correct_rate'])}; "
      f"`test2` {pc(T2['overall']['fields_micro']['exact_match'])} / {pc(T2['overall']['invoice_all_correct_rate'])}. Dev-guided fixes before the first `test` run: label+column-gap separators in spreadsheets, "
      "CSV delimiter detection by line statistics, retaining line items whose OCR'd quantity is unreadable. Dataset/scoring bugs I found and fixed on dev: spreadsheets without a printed currency, "
      "expected-rule key mismatch, and a false-review metric that counted correctly-flagged duplicates. The similarity of dev and held-out numbers means there is no sign of overfitting *to this generator*; "
      "it says nothing about real invoices.\n")

    A("## 7. Limitations and what was not measured\n")
    for s in ["Synthetic data from one author → optimistic; real-world accuracy is unknown. Expect lower numbers on unseen layouts, multi-line descriptions, discounts/shipping, tax-inclusive totals and noisy scans.",
              "Rule-based extractor only; no LLM extraction was evaluated (none is wired in). Confidence is heuristic (section 5.5).",
              "Small samples: 8–16 extraction errors per split; per-type and per-rule figures have wide intervals.",
              "Speed is from a 1-core Linux sandbox with 1–2 page files. 1,000-page behaviour is in `docs/benchmarks/`; **nothing was measured on the Windows / 8 GB target.**",
              "Matching of predicted to labeled invoices is by invoice number, falling back to order when counts agree; an OCR-misread number therefore counts as a field error rather than a missed invoice.",
              "Line-item matching requires description, quantity, unit price and amount all to equal; a row kept with an unreadable quantity counts as one miss and one wrong item (but is flagged `VAL-LINE-003`).",
              "Cross-document verification was evaluated on 14 synthetic pairs per split (header values only; line items are not compared).",
              "Semantic search is evaluated separately in `docs/SEMANTIC.md`; it is off in all runs here."]:
        A(f"- {s}")
    A("\n## 8. Reproduce\n")
    A("```\npython eval/make_dataset.py --split dev        # also: test, test2 (deterministic; ~7 MB each)\npython eval/run_eval.py --split test           # writes docs/evaluation/results_test.json + errors_test.jsonl\n"
      "python eval/run_eval.py --split test2 --ocr-floor 0 --tag _rule_off   # rule disabled\npython eval/run_eval.py --split test2          # current defaults\npython eval/report_eval.py                     # regenerates this file\n```")
    A("Raw per-run results (including per-field counts, timing, negative cases, calibration and the OCR sweep) are in `docs/evaluation/results_*.json`.")
    (D / "EVALUATION.md").write_text("\n".join(L) + "\n")
    print("\n".join(L))


if __name__ == "__main__":
    main()
